syntax:
element { property: value; }
.class { property: value; }
#id { property: value; }
[parent] > child { property: value; }
ancestor descendant { property: value; }
:where(selector-list) { property: value; }
:is(selector-list) { property: value; }
parent:has(> child:invalid) { property: value; }

@layer reset, components, overrides;
@layer components { .class { color: value; } }
.class { color: inherit; margin: initial; }
@layer earlier, later;
@layer later { selector { color: revert-layer; } }
selector { color: initial | inherit | unset | revert; }

.container { display: flex; flex-direction: row | column; flex-wrap: wrap; gap: length; justify-content: value; align-items: value; }
.item { flex: grow shrink basis; }
.item { flex: grow shrink basis; min-inline-size: 0; }

.container { display: grid; grid-template-columns: repeat(count, minmax(minimum, 1fr)); gap: length; }
.item { grid-column: start / end; }
selector { grid-template-columns: repeat(auto-fit, minmax(min(100%, minimum), 1fr)); grid-auto-rows: length; }
child { grid-column: span integer; grid-template-columns: subgrid; }

.parent { position: relative; }
.child { position: absolute; inset-block-start: length; inset-inline-end: length; }
.sticky { position: sticky; top: length; z-index: integer; }

.class { overflow: auto | hidden | clip | visible; }
.line { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
selector { overflow: auto | hidden | clip; }

.class:hover { property: value; }
.control:focus-visible { outline: width style color; }
input:checked + label { property: value; }
.item:nth-child(2n) { property: value; }

.class::before { content: "text"; }
.class::after { content: ""; display: block; }
input::placeholder { color: color; }

:root { --token: value; }
.class { property: var(--token, fallback); }
selector { color: var(--accent, fallback); }

.class { transition: property duration easing; transform: translateY(length) rotate(angle) scale(number); }
@media (prefers-reduced-motion: reduce) { .class { transition: none; transform: none; } }
selector { transition-property: opacity; transition-duration: time; }

@keyframes name { from { property: value; } to { property: value; } }
.class { animation: name duration easing iteration-count; }
selector { animation: name duration linear both; }

.custom-button { --bs-btn-bg: color; --bs-btn-border-color: color; --bs-btn-hover-bg: color; --bs-btn-hover-border-color: color; }
.custom:focus-visible { outline: width solid color; outline-offset: length; }
@media (min-width: breakpoint) { .actions { flex-direction: row; } }

@import "tailwindcss";
@theme { --color-name: color; --font-name: family; }
selector { @apply utility variant:utility; }
@source inline("utility");

@media (prefers-reduced-motion: reduce) { selector { animation: none; } }
selector { color-scheme: light dark; }
@media (forced-colors: active) { selector { border-color: ButtonText; } }

parent { counter-reset: name; }
child { counter-increment: name; }
child::before { content: counter(name); }
